        java: "import java.io.*;\nimport java.util.*;\nimport com.google.gson.*;\n\npublic class Main {\n    static Object solve(JsonObject data) {\n        int num = data.has(\"num\") ? data.get(\"num\").getAsInt() : 0;\n        int[] vals = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};\n        String[] sym = {\"M\", \"CM\", \"D\", \"CD\", \"C\", \"XC\", \"L\", \"XL\", \"X\", \"IX\", \"V\", \"IV\", \"I\"};\n        StringBuilder sb = new StringBuilder();\n        for (int k = 0; k < vals.length; k++) {\n            while (num >= vals[k]) { sb.append(sym[k]); num -= vals[k]; }\n        }\n        return sb.toString();\n    }\n\n    public static void main(String[] args) throws Exception {\n        JsonObject data = JsonParser.parseString(new String(System.in.readAllBytes())).getAsJsonObject();\n        Object result = solve(data);\n        System.out.println(new Gson().toJson(result));\n    }\n}\n",
        cpp: "#include <iostream>\n#include <string>\n#include <vector>\n#include <unordered_map>\n#include <unordered_set>\n#include <map>\n#include <set>\n#include <queue>\n#include <stack>\n#include <algorithm>\n#include <climits>\n#include \"json.hpp\"\nusing json = nlohmann::json;\n\njson solve(const json& data) {\n    int num = data.value(\"num\", 0);\n    std::vector<std::pair<int, std::string>> pairs = {\n        {1000, \"M\"}, {900, \"CM\"}, {500, \"D\"}, {400, \"CD\"},\n        {100, \"C\"}, {90, \"XC\"}, {50, \"L\"}, {40, \"XL\"},\n        {10, \"X\"}, {9, \"IX\"}, {5, \"V\"}, {4, \"IV\"}, {1, \"I\"}\n    };\n    std::string out;\n    for (auto [v, s] : pairs) while (num >= v) { out += s; num -= v; }\n    return out;\n}\n\nint main() {\n    json data;\n    std::cin >> data;\n    json result = solve(data);\n    std::cout << result.dump();\n    return 0;\n}\n",
