        java: "import java.io.*;\nimport java.util.*;\nimport com.google.gson.*;\n\npublic class Main {\n    static Object solve(JsonObject data) {\n        double x = data.has(\"x\") ? data.get(\"x\").getAsDouble() : 1.0;\n        long n = data.has(\"n\") ? data.get(\"n\").getAsLong() : 0;\n        if (n < 0) { x = 1.0 / x; n = -n; }\n        double ans = 1.0;\n        while (n > 0) {\n            if ((n & 1) == 1) ans *= x;\n            x *= x;\n            n >>= 1;\n        }\n        return ans;\n    }\n\n    public static void main(String[] args) throws Exception {\n        JsonObject data = JsonParser.parseString(new String(System.in.readAllBytes())).getAsJsonObject();\n        Object result = solve(data);\n        System.out.println(new Gson().toJson(result));\n    }\n}\n",
