        java: "import java.io.*;\nimport java.util.*;\nimport com.google.gson.*;\n\npublic class Main {\n    static Object solve(JsonObject data) {\n        JsonArray opsArr = data.has(\"ops\") ? data.getAsJsonArray(\"ops\") : new JsonArray();\n        JsonArray argsArr = data.has(\"args\") ? data.getAsJsonArray(\"args\") : new JsonArray();\n        List<int[]> bookings = new ArrayList<>();\n        List<Boolean> out = new ArrayList<>();\n        for (int i = 0; i < opsArr.size(); i++) {\n            if (!\"book\".equals(opsArr.get(i).getAsString())) continue;\n            JsonArray a = argsArr.get(i).getAsJsonArray();\n            int start = a.get(0).getAsInt();\n            int end = a.get(1).getAsInt();\n            boolean ok = true;\n            for (int[] b : bookings) {\n                if (start < b[1] && end > b[0]) { ok = false; break; }\n            }\n            if (ok) bookings.add(new int[]{start, end});\n            out.add(ok);\n        }\n        return out;\n    }\n\n    public static void main(String[] args) throws Exception {\n        JsonObject data = JsonParser.parseString(new String(System.in.readAllBytes())).getAsJsonObject();\n        Object result = solve(data);\n        System.out.println(new Gson().toJson(result));\n    }\n}\n",
